	@Test
	void anEstimateEliminatesNobody() {
		LmdbNativeCandidate<String> cheap = LmdbNativeCandidate.of("cheap", LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, 0D, 1D, UNBOUNDED), Double.NaN), () -> "cheap");
		LmdbNativeCandidate<String> costly = LmdbNativeCandidate.of("costly", LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, 0D, 1e12D, UNBOUNDED), Double.NaN), () -> "costly");

		LmdbNativeSelector.Ranking ranked = LmdbNativeSelector.rank(List.of(cheap, costly),
				LmdbNativeStaticPrior.DEFAULT, -1D);

		assertThat(ranked.estimated()[0].high()).isLessThan(ranked.estimated()[1].low());
		assertThat(ranked.eliminatedBy()).containsOnlyNulls();
		assertThat(ranked.winner()).isZero();
	}

