	@Test
	void aFilterCanRejectEveryRowSoItsFloorIsZero() {
		LmdbNativeRowSpread spread = LmdbNativeRowSpread.PROBE.mayRejectAll();

		assertThat(spread.down()).isInfinite();
		assertThat(spread.up()).isEqualTo(LmdbNativeRowSpread.PROBE.up());
	}

	@Test
	void independentErrorsAddInQuadratureAndAUnionKeepsTheWiderSide() {
		LmdbNativeRowSpread chain = LmdbNativeRowSpread.PROBE.times(LmdbNativeRowSpread.PROBE)
				.times(LmdbNativeRowSpread.PROBE)
				.times(LmdbNativeRowSpread.PROBE);

		assertThat(chain.up()).as("sqrt(4) probes wide on a log scale").isCloseTo(4D, within(1e-9));
		assertThat(LmdbNativeRowSpread.EXACT.times(LmdbNativeRowSpread.PROBE).up())
				.isCloseTo(LmdbNativeRowSpread.PROBE.up(), within(1e-9));
		assertThat(LmdbNativeRowSpread.UNKNOWN.times(LmdbNativeRowSpread.PROBE).known()).isFalse();
		assertThat(LmdbNativeRowSpread.SCAN.widest(LmdbNativeRowSpread.PROBE)).isEqualTo(LmdbNativeRowSpread.PROBE);
	}

	@Test
	void aQuoteWithNoProvenCeilingCompetesOnItsExpectation() {
		LmdbNativeCandidate<String> estimated = LmdbNativeCandidate.of("estimated", LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, 0D, 5D, UNBOUNDED), Double.NaN), () -> "estimated");
		LmdbNativeCandidate<String> proven = LmdbNativeCandidate.of("proven", LmdbNativeCostQuote.streaming(
				LmdbNativeCostVector.point(Feature.SCANNED_ROW, 100D), Double.NaN), () -> "proven");

		LmdbNativeSelector.Ranking ranked = LmdbNativeSelector.rank(List.of(proven, estimated),
				LmdbNativeStaticPrior.DEFAULT, -1D);

		assertThat(ranked.winner()).isEqualTo(1);
		assertThat(ranked.eliminatedBy()).containsOnlyNulls();
		assertThat(ranked.nanos()[1].known()).isFalse();
	}

